import { ARTICLES } from "@/articles";
import { Link, useRoute } from "wouter";
import NotFound from "./NotFound";

export default function Article() {
  const [match, params] = useRoute("/blog/:slug");

  if (!match || !params || !params.slug) {
    return <NotFound />;
  }

  const article = ARTICLES.find((a) => a.slug === params.slug);

  if (!article) {
    return <NotFound />;
  }

  return (
    <div className="min-h-screen bg-background text-foreground">
      <header className="sticky top-0 z-50 bg-white/80 backdrop-blur-md border-b border-border">
        <div className="container max-w-6xl mx-auto px-4 py-4 flex items-center justify-between">
          <div className="text-xl font-bold text-accent">Mohsen Baranizadeh</div>
          <nav className="flex gap-8">
            <Link href="/" className="hover:text-accent transition">
              Home
            </Link>
            <Link href="/blog" className="hover:text-accent transition">
              Blog
            </Link>
          </nav>
        </div>
      </header>

      <section className="py-16 md:py-24 bg-gradient-to-b from-blue-50 to-white">
        <div className="container max-w-3xl mx-auto px-4">
          <div className="space-y-4 mb-12">
            <h1 className="text-4xl md:text-5xl font-bold text-foreground leading-tight">
              {article.title}
            </h1>
            <p className="text-lg text-muted-foreground">
              Published on {article.date}
            </p>
            <Link href="/blog">
              <a className="text-accent font-semibold hover:underline flex items-center gap-1">
                &larr; Back to Blog
              </a>
            </Link>
          </div>

          <div className="prose max-w-none text-lg text-muted-foreground">
            {article.content}
          </div>
        </div>
      </section>

      {/* Footer - Reusing the Home page footer structure for consistency */}
      <footer className="bg-foreground text-white py-12">
        <div className="container max-w-6xl mx-auto px-4">
          <div className="text-center text-white/50 text-sm">
            <p>&copy; 2025 Mohsen Baranizadeh. All rights reserved.</p>
          </div>
        </div>
      </footer>
    </div>
  );
}
